// The demo (DBU-11): window.dbuDemo is made by demo/boot.js, which only the demo's page loads.
const d = typeof window !== 'undefined' ? window.dbuDemo : undefined;
const say = (supported) => {
  Outputs.isDemo = !!d;
  Outputs.notDemo = !d;
  Outputs.supported = !!d && supported;
  Outputs.unsupported = !!d && !supported;
  const persona = (d && d.persona) || '';
  Outputs.coachView = persona === 'richard';
  Outputs.learnerView = !!d && persona !== 'richard';
};
say(!!(d && d.supported));
if (d && d.ready) d.ready.then((ok) => { if (ok === false) say(false); });
